#include "stdlib/lapack/base/dlantr.h"
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define NAME "dlantr"
#define REPEATS 3
#define ITERATIONS 10000

/**
* Runs a matrix norm benchmark.
*
* @param N       matrix dimension
* @param norm    norm type
* @return        elapsed time in seconds
*/
static double benchmark( const LAPACK_INT N, const char norm ) {
	double *work;
	double *A;
	double out;
	clock_t t;
	LAPACK_INT i;

	A = (double *)malloc( N*N*sizeof( double ) );
	work = (double *)malloc( N*sizeof( double ) );
	if ( A == NULL || work == NULL ) {
		free( A );
		free( work );
		exit( 1 );
	}
	for ( i = 0; i < N*N; i++ ) {
		A[ i ] = (i%19) - 9;
	}
	t = clock();
	for ( i = 0; i < ITERATIONS; i++ ) {
		out = API_SUFFIX(c_dlantr)( LAPACK_ROW_MAJOR, norm, LAPACK_UPPER_TRIANGLE, LAPACK_NON_UNIT_DIAGONAL, N, N, A, N, work );
		if ( out != out ) {
			free( A );
			free( work );
			exit( 1 );
		}
	}
	t = clock() - t;
	free( A );
	free( work );
	return (double)t / CLOCKS_PER_SEC;
}

int main( void ) {
	const char norms[] = { 'M', '1', 'I', 'F' };
	double elapsed;
	int count;
	int i;
	int j;

	printf( "TAP version 13\n" );
	count = 0;
	for ( i = 0; i < 4; i++ ) {
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			elapsed = benchmark( 10, norms[ i ] );
			printf( "# c::%s:norm=%c,N=10\n", NAME, norms[ i ] );
			printf( "  ---\n  iterations: %d\n  elapsed: %0.9f\n  rate: %0.9f\n  ...\n", ITERATIONS, elapsed, ITERATIONS/elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	printf( "1..%d\n# total %d\n# pass %d\n# ok\n", count, count, count );
	return 0;
}
